test('re-running the migration after a partial failure is safe', async () => {
  const db = new PGlite()
  await migrate(db, await migrationsBefore0005())
  // Simulate the state after steps 1-3 ran but the file was not recorded: run the
  // file's own SQL twice, which is what a retried deploy does.
  const file = join(MIGRATIONS, '0005_orders_customer_fk_and_total_check.sql')
  const { readFile } = await import('node:fs/promises')
  const { splitStatements } = await import('../src/migrate.ts')
  const statements = await splitStatements(await readFile(file, 'utf8'))
  for (const statement of statements) await db.query(statement)
  for (const statement of statements) await db.query(statement)
  const count = await scalar<number>(
    db,
    `SELECT count(*)::int FROM pg_constraint WHERE conname IN ('orders_customer_id_fkey', 'orders_total_cents_nonnegative')`,
